import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;

public class Main {
    public static void main(String[] args) throws Exception {
        Thread t = new Thread(() -> {
            try {
                Thread.sleep(5000);
                System.out.println("bangun sendiri");
            } catch (InterruptedException e) {
                System.out.println("dibangunkan lebih awal");
            }
        });
        t.start();
        Thread.sleep(100);
        t.interrupt();
        t.join();
    }
}

