import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;

public class Main {
    static String kirimSemua(List<String> pesanan) {
        int terkirim = 0;
        for (String p : pesanan) {
            if (Thread.currentThread().isInterrupted()) {
                return "dihentikan setelah " + terkirim + " pesanan";
            }
            try {
                Thread.sleep(100);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                return "dihentikan setelah " + terkirim + " pesanan";
            }
            terkirim++;
        }
        return "semua " + terkirim + " pesanan terkirim";
    }

    public static void main(String[] args) throws Exception {
        List<String> pesanan = List.of("PSN-1", "PSN-2", "PSN-3", "PSN-4", "PSN-5", "PSN-6", "PSN-7", "PSN-8", "PSN-9", "PSN-10");
        ExecutorService pool = Executors.newSingleThreadExecutor();
        Future<String> kirim = pool.submit(() -> kirimSemua(pesanan));
        System.out.println(kirim.get());
        pool.shutdown();
    }
}

