import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        Scanner in = new Scanner(System.in);
        List<String> nama = new ArrayList<>();
        while (in.hasNextLine()) {
            nama.add(in.nextLine().trim());
        }
        String[] hasil = new String[nama.size()];
        List<Thread> request = new ArrayList<>();
        for (int i = 0; i < nama.size(); i++) {
            int ke = i;
            request.add(new Thread(() -> {
                Konteks.pengguna.set(nama.get(ke));
                try {
                    Jeda.ms(100);
                    hasil[ke] = "request " + (ke + 1) + " milik " + Konteks.pengguna.get();
                } finally {
                    Konteks.pengguna.remove();
                }
            }));
        }
        for (Thread t : request) {
            t.start();
        }
        for (Thread t : request) {
            t.join();
        }
        for (String h : hasil) {
            System.out.println(h);
        }
    }
}

class Konteks {
    static final ThreadLocal<String> pengguna = new ThreadLocal<>();
}

class Jeda {
    static void ms(long ms) {
        try {
            Thread.sleep(ms);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }
}
